/* From Uiverse.io by ahmedyasserdev  - Tags: card, hover effect, cardhover , card hover, 3d card */
.__UIV_SCOPE__ .three-d-card {
  position: relative;
  width: 300px;
  height: 200px;
  perspective: 1000px;
}

.__UIV_SCOPE__ .card-wrapper {
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  transition: transform 0.5s;
}

.__UIV_SCOPE__ .three-d-card:hover .card-wrapper {
  transform: rotateY(180deg);
}

.__UIV_SCOPE__ .card-face {
  position: absolute;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid #3498db;
  border-radius: 15px;
  background-color: #fff;
}

.__UIV_SCOPE__ .card-face.front {
  transform: rotateY(0deg);
}

.__UIV_SCOPE__ .card-face.back {
  transform: rotateY(180deg);
}

.__UIV_SCOPE__ .card-content {
  text-align: center;
  color: #333;
}

.__UIV_SCOPE__ .card-title {
  font-size: 24px;
  font-weight: bold;
  margin-bottom: 10px;
}

.__UIV_SCOPE__ .card-description {
  font-size: 16px;
}
